-- Static Slaghammer101430: admitted owner and acknowledged native201004 handoff.
-- Requires matching instance-owned handoff/derived SmartAI binary; keep outside updater until promotion.
-- Native SmartAI payload/unknown LINK2 are preserved unchanged.
SET @slaghammer_handoff_concat=@@session.group_concat_max_len;
SET SESSION group_concat_max_len=1048576;
START TRANSACTION;
SET @slaghammer_handoff_scripts=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`id` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`link` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_z` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_o` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `id` SEPARATOR '\n'),''),256) FROM smart_scripts WHERE entryorguid=101430 AND source_type=0);
SET @slaghammer_handoff_conditions=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `SourceGroup`,`ElseGroup`,`ConditionTypeOrReference` SEPARATOR '\n'),''),256) FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=101430);

SET @slaghammer_handoff_safe=(@slaghammer_handoff_scripts='a3c3f6ad5f57cc6824400112be9f11245e9bb3a7551ae8772fbb41c13080d8e4'
 AND @slaghammer_handoff_conditions='c524d47d94bfccf7f22c3607aef2e261c48b831170a2c8378e0e0a955d0cca0e'
 AND (SELECT COUNT(*) FROM creature_template WHERE entry=101430 AND AIName='SmartAI' AND ScriptName IN('','npc_slaghammer_handoff'))=1
 AND (SELECT COUNT(*) FROM instance_template WHERE map=1539 AND script='instance_silver_hand')=1
 AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id=201004)=0
 AND (SELECT COUNT(*) FROM waypoints WHERE entry=101430)=1
 AND (SELECT COUNT(*) FROM waypoints WHERE entry=101430 AND pointid=1 AND ABS(position_x-2020.16)<0.001 AND ABS(position_y-2337.81)<0.001 AND ABS(position_z-75.2808)<0.001)=1);
SET @slaghammer_handoff_guard=IF(COALESCE(@slaghammer_handoff_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Slaghammer handoff native graph/binding/path differ; review before updating''');
PREPARE slaghammer_handoff_guard FROM @slaghammer_handoff_guard;
EXECUTE slaghammer_handoff_guard;
DEALLOCATE PREPARE slaghammer_handoff_guard;
UPDATE creature_template SET ScriptName='npc_slaghammer_handoff' WHERE @slaghammer_handoff_safe AND entry=101430 AND AIName='SmartAI' AND ScriptName='';
COMMIT;
SET SESSION group_concat_max_len=@slaghammer_handoff_concat;
